#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum TemporalQuality{PreviewLow,PreviewFull,Final}
pub fn sample_times(frame:f32,shutter_angle:f32,phase:f32,samples:u32,quality:TemporalQuality)->Vec<f32>{let cap=match quality{TemporalQuality::PreviewLow=>4,TemporalQuality::PreviewFull=>8,TemporalQuality::Final=>64};let n=samples.clamp(1,cap);if n==1||shutter_angle<=0.{return vec![frame]}let span=shutter_angle.clamp(0.,720.)/360.;let center=frame+phase/360.;let start=center-span/2.;(0..n).map(|i|start+span*i as f32/(n-1)as f32).collect()}
